sys_script_include.script:
var AssignmentScorer = Class.create();
AssignmentScorer.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    computeScore: function(userSysId, taskGr) {
        var score = 0;

        // 1) Skill match
        var skillMatch = 0;
        if (taskGr.requested_skill) {
            var gr1 = new GlideRecord('x_1259673_intell_0_user_competency');
            gr1.addQuery('user', userSysId);
            gr1.addQuery('competency', taskGr.requested_skill);
            gr1.query();
            if (gr1.next()) {
                skillMatch = (parseInt(gr1.level, 10) - 1) / 4.0; // normalize 1-5 -> 0-1
            }
        }

        // 2) Availability
		var now = new GlideDateTime();
        var available = true;
        var av = new GlideRecord('x_1259673_intell_0_availability');
        av.addQuery('user', userSysId);
        av.addQuery('from', '<=', now);
        av.addQuery('to', '>=', now);
        av.query();
        if (av.next()) available = false;
        var availabilityScore = available ? 1 : 0;

        // 3) Workload
        var gr = new GlideAggregate('x_1259673_intell_0_incident');
        gr.addQuery('assigned_to', userSysId);
        gr.addQuery('state', '<', 7);
        gr.addAggregate('COUNT');
        gr.query();
        var openCount = 0;
        if (gr.next()) openCount = parseInt(gr.getAggregate('COUNT'), 10);
        var workloadScore = Math.max(0, 1 - (openCount / 20.0));

        // 4) Performance (dummy logic)
        var perfScore = 0.5; // par défaut

        // Weighted total
        score = 50 * skillMatch + 20 * availabilityScore + 15 * workloadScore + 15 * perfScore;

        return Math.round(score);
    },

    findBestAssignee: function(taskGr) {
        var candidates = [];
        var ucomp = new GlideRecord('x_1259673_intell_0_user_competency');
        ucomp.query();
        while (ucomp.next()) {
            var s = this.computeScore(ucomp.user.toString(), taskGr);
            candidates.push({
                user: ucomp.user.toString(),
                score: s
            });
        }
        if (candidates.length === 0) return null;
        candidates.sort(function(a, b) {
            return b.score - a.score;
        });

        return candidates[0];
    },

    type: 'AssignmentScorer'
});
